BASE = os.path.join(HERE, "..", "paper1"); OUT = os.path.join(BASE, "output"); os.makedirs(OUT, exist_ok=True)
R = json.load(open(os.path.join(OUT, "results_paper1.json"), encoding="utf-8"))
P, IND, REL, SEM, CFA = R["paths"], R["indirect"], R["rel"], R["sem"], R["cfa"]
d = Doc(); cited = set()

def K(key, paren=False):
    cited.add(key); fa_n, en_n, yr = CITE[key]
    if en_n is None: return f"({fa_n}، {yr})" if paren else f"{fa_n} ({yr})"
    mark = "" if en_n in d.seen else f"[[fn:{en_n}]]"; d.seen.add(en_n)
    return f"({fa_n}{mark}، {yr})" if paren else f"{fa_n}{mark} ({yr})"
def KK(*keys):
    parts = []
    for key in keys:
        cited.add(key); fa_n, en_n, yr = CITE[key]
        mark = "" if (en_n is None or en_n in d.seen) else f"[[fn:{en_n}]]"
        if en_n: d.seen.add(en_n)
        parts.append(f"{fa_n}{mark}، {yr}")
    return "(" + "؛ ".join(parts) + ")"
def T(fa_term, en_term):
    mark = "" if en_term in d.seen else f"[[fn:{en_term}]]"; d.seen.add(en_term); return f"{fa_term}{mark}"
f2 = lambda x: fa(f"{x:.2f}"); f3 = lambda x: fa(f"{x:.3f}"); F1 = lambda x: fa(f"{x:.1f}"); F0 = lambda x: fa(f"{x:.0f}")
def sig(p): return "∗∗∗" if p < .001 else "∗∗" if p < .01 else "∗" if p < .05 else "ns"
def pt(p): return pval(p) if p < .001 else fa("p = " + format(p, ".3f"))
def stat(k): v = P[k]; return f"{S('β = ' + format(v['beta'], '.2f'))}، {S('z = ' + format(v['z'], '.2f'))}، {pt(v['p'])}"
def ci(k): v = IND[k]; return f"[{num(v['lo'], 3)}، {num(v['hi'], 3)}]"
ks = ["SME", "FOMO", "HRD", "AIU", "IDQ"]
NM = {"SME": "مواجهه با محتوا (SME)", "FOMO": "فومو (FOMO)", "HRD": "رفتار توده‌وار (HRD)", "AIU": "اطلاعات حسابداری (AIU)", "IDQ": "کیفیت تصمیم (IDQ)"}
NM0 = {"SME": "مواجهه با محتوای سرمایه‌گذاری در شبکه‌های اجتماعی", "FOMO": "فومو", "HRD": "رفتار توده‌وار", "AIU": "استفاده از اطلاعات حسابداری", "IDQ": "کیفیت تصمیم سرمایه‌گذاری"}
sdl = R["sd_latent"]
def std_slope(t): return IND[f"slope_FOMO_HRD_{t}"]["est"]*sdl["FOMO"]/sdl["HRD"]

# ---- پیش‌بررسی منطقی نتایج
assert P["FOMO~SME"]["p"] < .001 and P["HRD~FOMO"]["p"] < .001 and P["IDQ~HRD"]["p"] < .001 and P["HRD~SME"]["p"] < .01 and P["IDQ~AIU"]["p"] < .001
assert P["HRD~INT"]["p"] < .05 and P["HRD~INT"]["b"] < 0
assert IND["ind_SME_FOMO_HRD_IDQ_mean"]["sig"] and IND["imm"]["sig"] and IND["imm"]["est"] > 0 and IND["std_seq"]["sig"]
assert CFA["cfi"] >= .95 and CFA["rmsea"] <= .06 and CFA["srmr"] <= .08 and SEM["cfi"] >= .95

# ---- شکل‌ها
sem_figs.sem_paper1(os.path.join(OUT, "fig1_conceptual.png"), R, conceptual=True)
sem_figs.sem_paper1(os.path.join(OUT, "fig2_results.png"), R)
def fig_interaction(path):
    fig, ax = plt.subplots(figsize=(6.4, 4.4)); xs = np.linspace(-2, 2, 50)
    for k, col, ls, tag, lab in [(-1, "#b2182b", "-", "low", "اطلاعات حسابداری پایین (−۱ انحراف معیار)"), (0, "#555555", "--", "mean", "میانگین"), (1, "#2166ac", "-", "high", "اطلاعات حسابداری بالا (+۱ انحراف معیار)")]:
        ax.plot(xs, std_slope(tag)*xs, color=col, ls=ls, lw=2.2, label=fl.fa(lab))
    ax.set_xlabel(fl.fa("فومو (متغیر پنهان، نمرهٔ استاندارد)")); ax.set_ylabel(fl.fa("رفتار توده‌وار (پنهان، پیش‌بینی‌شده)"))
    ax.set_xticks([-2, -1, 0, 1, 2]); ax.set_xticklabels([fl.num(t, 0) for t in [-2, -1, 0, 1, 2]])
    yt = ax.get_yticks(); ax.set_yticks(yt); ax.set_yticklabels([fl.num(t, 1) for t in yt])
    ax.legend(frameon=False, fontsize=9, loc="upper left"); ax.spines[["top", "right"]].set_visible(False); fig.tight_layout()
    fig.savefig(path, dpi=220, facecolor="white"); plt.close(fig)
fig_interaction(os.path.join(OUT, "fig3_interaction.png"))

