d.para(f"بر پایهٔ جدول‌های ۹ تا ۱۱، هر هشت فرضیه تأیید شد: فرضیه‌های ۱ تا ۴ و ۸ بر پایهٔ ضرایب مسیر معنادار، فرضیهٔ ۵ بر پایهٔ فاصلهٔ اطمینان اثر غیرمستقیم متوالی ({num(I_['std_seq']['est'], 3)}؛ {ci('std_seq')})، فرضیهٔ ۶ بر پایهٔ ضریب تعامل منفی و معنادار ({num(P['HRD~INT']['beta'], 3)}) و فرضیهٔ ۷ بر پایهٔ شاخص میانجی‌گری تعدیل‌شدهٔ مثبت ({num(I_['imm']['est'], 3)}؛ {ci('imm')}).")
d.heading("۴-۸. آزمون‌های تکمیلی و استحکام", 2)
M = R["models"]
d.para(f"نخست، چهار مدل ساختاری رقیب مقایسه شد (جدول ۱۲). مدل پیشنهادی (میانجی جزئی) از مدل میانجی کامل زنجیره‌ای بهتر برازش داشت ({S('Δχ² = ' + format(M['M2']['chi2'] - M['M1']['chi2'], '.1f'))}؛ {S('Δdf = ' + format(M['M2']['df'] - M['M1']['df'], '.0f'))}) و مدل بدون میانجی (اثر مستقیم) برازش ضعیف‌تری داشت. مدل با ترتیب معکوس (توده‌واری ← فومو) از نظر آماری هم‌ارز مدل پیشنهادی است (درجهٔ آزادی برابر)؛ از این‌رو ترتیب علّی بر پایهٔ منطق نظری و نه یافتهٔ آماری انتخاب شده و این موضوع در محدودیت‌ها آمده است.")
d.table("جدول ۱۲. مقایسهٔ مدل‌های رقیب", ["مدل", "χ²", "df", "CFI", "RMSEA", "BIC"],
        [[M[k]["name"], F1(M[k]["chi2"]), F0(M[k]["df"]), f3(M[k]["cfi"]), f3(M[k]["rmsea"]), F1(M[k]["bic"])] for k in ["M1", "M2", "M3", "M4"]], widths=[3700, 1000, 700, 900, 900, 1100])
