        sens("تعامل با مرکزسازی باقی‌مانده", R["resid_centered_fit"], rc["HRD~FOMO"]["beta"], rc["IDQ~HRD"]["beta"], rc["HRD~INT"]["beta"], "شاخص‌های متعامد"),
        sens("بازمشخص‌سازی (۴ خطای همبسته)", rs["fit"], rs["paths"]["HRD~FOMO"]["beta"], rs["paths"]["IDQ~HRD"]["beta"], rs["paths"]["HRD~INT"]["beta"], "آزادسازی خطاها"),
